@app.post("/api/sessions/{session_id}/mock")
async def mock_transcript(session_id: str):
    """Inject 3 fake debate entries to trigger analysis. Call multiple times."""
    session_id = session_id.upper()
    session = sessions.get(session_id)
    if not session:
        raise HTTPException(status_code=404, detail="Session not found")

    idx = mock_index.get(session_id, 0)
    if idx >= len(MOCK_DEBATE):
        mock_index[session_id] = 0
        idx = 0

    added = []
    for i in range(3):
        if idx + i >= len(MOCK_DEBATE):
            break
        speaker, text = MOCK_DEBATE[idx + i]
        entry = {
            "type": "transcript",
            "text": text,
            "speaker": speaker,
            "timestamp": time.time() + i,
        }
        should_analyze = sessions.add_transcript_entry(session_id, entry)
        await sessions.broadcast(session_id, entry)
        added.append(entry)

        if should_analyze:
            sessions.mark_analysis_started(session_id)
            asyncio.create_task(run_analysis(session_id))

    mock_index[session_id] = idx + len(added)
    return {
        "added": len(added),
        "total": len(session.transcript),
        "remaining": max(0, len(MOCK_DEBATE) - mock_index[session_id]),
    }
```

**Analysis trigger flow:**
- When `should_analyze` is True (3+ transcript entries since last analysis):
  - Calls `sessions.mark_analysis_started(session_id)`
  - Launches `asyncio.create_task(run_analysis(session_id))`
  - `run_analysis()` calls `analysis.extract_statements()` with transcript, existing statements, and topic
  - New statements are added with `sessions.add_statements(session_id, new_texts)`
  - Broadcasts updated statements with `sessions.broadcast_statements(session_id)`
  - Checks round completion with `sessions.check_and_advance_round(session_id)`
  - If round completes, broadcasts `'threshold_reached'` message

